create extension if not exists pgcrypto;
create type public.execution_mode as enum ('AUTO','APPROVE','BLOCKED');
create type public.mission_status as enum ('draft','active','paused','completed');
create type public.action_status as enum ('planned','waiting_approval','queued','running','succeeded','failed','blocked','cancelled');

create table public.workspaces(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Margaryan Labs',created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,name text not null,one_liner text not null default '',website_url text,languages text[] not null default array['en','ru']::text[],target_customer jsonb not null default '{}'::jsonb,positioning jsonb not null default '{}'::jsonb,proof jsonb not null default '{}'::jsonb,pricing jsonb not null default '{}'::jsonb,objections jsonb not null default '{}'::jsonb,forbidden_claims text[] not null default '{}'::text[],created_at timestamptz not null default now());
create table public.missions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,product_id uuid references public.products(id) on delete set null,name text not null,goal text not null,market text not null default 'Global',language text not null default 'en' check(language in('en','ru')),autonomy text not null default 'approve' check(autonomy in('auto','approve','draft')),status public.mission_status not null default 'draft',plan jsonb not null default '{}'::jsonb,success_metrics jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.leads(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,mission_id uuid references public.missions(id) on delete cascade,company text,contact_name text,role text,email text,phone text,linkedin_url text,website_url text,country text,timezone text,language text check(language in('en','ru') or language is null),score integer not null default 0 check(score between 0 and 100),stage text not null default 'new',research jsonb not null default '{}'::jsonb,opted_out boolean not null default false,do_not_call boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.actions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,mission_id uuid references public.missions(id) on delete cascade,lead_id uuid references public.leads(id) on delete set null,channel text not null check(channel in('email','voice','linkedin','instagram','x','system')),kind text not null,mode public.execution_mode not null default 'APPROVE',status public.action_status not null default 'planned',payload jsonb not null default '{}'::jsonb,result jsonb,idempotency_key text unique,scheduled_for timestamptz,approved_by uuid references auth.users(id) on delete set null,approved_at timestamptz,executed_at timestamptz,retry_count integer not null default 0,error text,created_at timestamptz not null default now());
create table public.conversations(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,lead_id uuid references public.leads(id) on delete set null,channel text not null,external_thread_id text,transcript text,summary jsonb,sentiment text,outcome text,next_action text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.content_assets(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,mission_id uuid references public.missions(id) on delete cascade,type text not null,title text,body text,media_url text,variants jsonb not null default '{}'::jsonb,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table public.channel_accounts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,channel text not null check(channel in('email','voice','linkedin','instagram','x')),display_name text,provider_account_id text,status text not null default 'disconnected',capabilities jsonb not null default '{}'::jsonb,token_ref text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(workspace_id,channel,provider_account_id));
create table public.compliance_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete cascade,lead_id uuid references public.leads(id) on delete set null,action_id uuid references public.actions(id) on delete set null,channel text,decision text not null check(decision in('allow','block','manual_review')),reason text,context jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());

revoke all on all tables in schema public from anon;
grant select,insert,update,delete on public.workspaces,public.products,public.missions,public.leads,public.actions,public.conversations,public.content_assets,public.channel_accounts,public.compliance_events to authenticated;
alter table public.workspaces enable row level security; alter table public.products enable row level security; alter table public.missions enable row level security; alter table public.leads enable row level security; alter table public.actions enable row level security; alter table public.conversations enable row level security; alter table public.content_assets enable row level security; alter table public.channel_accounts enable row level security; alter table public.compliance_events enable row level security;
create policy "owners manage workspaces" on public.workspaces for all to authenticated using((select auth.uid())=owner_id) with check((select auth.uid())=owner_id);
create or replace function public.owns_workspace(target uuid) returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.workspaces w where w.id=target and w.owner_id=(select auth.uid())); $$;
revoke all on function public.owns_workspace(uuid) from public,anon; grant execute on function public.owns_workspace(uuid) to authenticated;
create policy "products owner" on public.products for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "missions owner" on public.missions for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "leads owner" on public.leads for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "actions owner" on public.actions for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "conversations owner" on public.conversations for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "content owner" on public.content_assets for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "accounts owner" on public.channel_accounts for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create policy "compliance owner" on public.compliance_events for all to authenticated using(public.owns_workspace(workspace_id)) with check(public.owns_workspace(workspace_id));
create index leads_mission_score_idx on public.leads(mission_id,score desc); create index actions_due_idx on public.actions(status,scheduled_for); create index conversations_lead_idx on public.conversations(lead_id,created_at desc); create index content_mission_idx on public.content_assets(mission_id,created_at desc);
